import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

ln_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor weight,
                                torch::Tensor bias,
                                double eps);
"""

ln_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>

#include <algorithm>
#include <climits>
#include <cstdint>

#include <cute/tensor.hpp>

using namespace cute;
namespace cg = cooperative_groups;

constexpr int kThreads = 1024;
constexpr int kWarps = kThreads / 32;

__global__ void cute_layernorm_reduce_kernel(
    const float4* __restrict__ X4,
    float* __restrict__ stats,
    int rows,
    int n4,
    int blocks_per_row,
    int total_units)
{
  const int tid = threadIdx.x;
  const int lane = tid & 31;
  const int warp_id = tid >> 5;
  Tensor mX = make_tensor(
      make_gmem_ptr(X4),
      make_shape(rows, n4),
      make_stride(n4, Int<1>{})
  );
  Tensor gStats = make_tensor(
      make_gmem_ptr(stats),
      make_shape(rows, Int<2>{}),
      make_stride(Int<2>{}, Int<1>{})
  );
  __shared__ float partial_raw[kWarps * 2];
  Tensor sPartial = make_tensor(
      make_smem_ptr(partial_raw),
      make_shape(Int<kWarps>{}, Int<2>{}),
      make_stride(Int<2>{}, Int<1>{})
  );
  const auto matrix_tiler = make_shape(Int<1>{}, Int<kThreads>{});
  const int num_tiles = (n4 + kThreads - 1) / kThreads;
  // Cooperatively reduce every row using multiple CTAs.
  // No cooperative launch or grid sync is required: each CTA
  // atomically accumulates its partial (sum, sum-of-squares) pair.
  for (int unit = static_cast<int>(blockIdx.x);
       unit < total_units;
       unit += static_cast<int>(gridDim.x)) {
    const int row = unit / blocks_per_row;
    const int part = unit - row * blocks_per_row;
    float sum = 0.0f;
    float sqsum = 0.0f;
    for (int tile = part; tile < num_tiles; tile += blocks_per_row) {
      const int idx = tile * kThreads + tid;
      if (idx < n4) {
        Tensor gX = local_tile(mX, matrix_tiler, make_coord(row, tile));
        const float4 xv = gX(0, tid);
        sum += xv.x + xv.y + xv.z + xv.w;
        sqsum = fmaf(xv.x, xv.x, sqsum);
        sqsum = fmaf(xv.y, xv.y, sqsum);
        sqsum = fmaf(xv.z, xv.z, sqsum);
        sqsum = fmaf(xv.w, xv.w, sqsum);
      }
    }
    // Warp reduction.
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum   += __shfl_down_sync(0xffffffffu, sum, offset);
      sqsum += __shfl_down_sync(0xffffffffu, sqsum, offset);
    }
    if (lane == 0) {
      sPartial(warp_id, 0) = sum;
      sPartial(warp_id, 1) = sqsum;
    }
    __syncthreads();
    // Final reduction by the first warp.
    if (warp_id == 0) {
      float block_sum = (lane < kWarps) ? sPartial(lane, 0) : 0.0f;
      float block_sqsum = (lane < kWarps) ? sPartial(lane, 1) : 0.0f;
      #pragma unroll
      for (int offset = 16; offset > 0; offset >>= 1) {
        block_sum   += __shfl_down_sync(0xffffffffu, block_sum, offset);
        block_sqsum += __shfl_down_sync(0xffffffffu, block_sqsum, offset);
      }
      if (lane == 0) {
        atomicAdd(&gStats(row, 0), block_sum);
        atomicAdd(&gStats(row, 1), block_sqsum);
      }
    }
    // Ensure partials from this reduction are not overwritten while still in use.
    __syncthreads();
  }
}
__global__ void cute_layernorm_normalize_kernel(
    const float4* __restrict__ X4,
    const float4* __restrict__ W4,
    const float4* __restrict__ B4,
    float4* __restrict__ Y4,
    const float* __restrict__ stats,
    int rows,
    int n4,
    float inv_n,
    float eps,
    int blocks_per_row,
    int total_units)
{
  const int tid = threadIdx.x;
  Tensor mX = make_tensor(
      make_gmem_ptr(X4),
      make_shape(rows, n4),
      make_stride(n4, Int<1>{})
  );
  Tensor mY = make_tensor(
      make_gmem_ptr(Y4),
      make_shape(rows, n4),
      make_stride(n4, Int<1>{})
  );
  Tensor mW = make_tensor(
      make_gmem_ptr(W4),
      make_shape(n4),
      make_stride(Int<1>{})
  );
  Tensor mB = make_tensor(
      make_gmem_ptr(B4),
      make_shape(n4),
      make_stride(Int<1>{})
  );
  Tensor gStats = make_tensor(
      make_gmem_ptr(stats),
      make_shape(rows, Int<2>{}),
      make_stride(Int<2>{}, Int<1>{})
  );
  const auto matrix_tiler = make_shape(Int<1>{}, Int<kThreads>{});
  const auto vector_tiler = make_shape(Int<kThreads>{});
  const int num_tiles = (n4 + kThreads - 1) / kThreads;
  // Normalize using the finalized per-row statistics produced by the
  // reduction kernel (kernel completion guarantees visibility).
  for (int unit = static_cast<int>(blockIdx.x);
       unit < total_units;
       unit += static_cast<int>(gridDim.x)) {
    const int row = unit / blocks_per_row;
    const int part = unit - row * blocks_per_row;
    const float total_sum = gStats(row, 0);
    const float total_sqsum = gStats(row, 1);
    const float mean = total_sum * inv_n;
    float var = total_sqsum * inv_n - mean * mean;
    var = fmaxf(var, 0.0f);
    const float rstd = rsqrtf(var + eps);
    for (int tile = part; tile < num_tiles; tile += blocks_per_row) {
      const int idx = tile * kThreads + tid;
      if (idx < n4) {
        Tensor gX = local_tile(mX, matrix_tiler, make_coord(row, tile));
        Tensor gY = local_tile(mY, matrix_tiler, make_coord(row, tile));
        Tensor gW = local_tile(mW, vector_tiler, make_coord(tile));
        Tensor gB = local_tile(mB, vector_tiler, make_coord(tile));
        const float4 xv = gX(0, tid);
        const float4 wv = gW(tid);
        const float4 bv = gB(tid);
        float4 yv;
        yv.x = (xv.x - mean) * rstd * wv.x + bv.x;
        yv.y = (xv.y - mean) * rstd * wv.y + bv.y;
        yv.z = (xv.z - mean) * rstd * wv.z + bv.z;
        yv.w = (xv.w - mean) * rstd * wv.w + bv.w;
        gY(0, tid) = yv;
      }
    }
  }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor weight,
                                torch::Tensor bias,
                                double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
  TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
  TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
  TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");

  TORCH_CHECK(x.dim() >= weight.dim(), "x must contain the normalized trailing dimensions");
  TORCH_CHECK(weight.dim() == bias.dim(), "weight and bias must have the same rank");

  const int64_t x_rank = x.dim();
  const int64_t w_rank = weight.dim();
  for (int64_t i = 0; i < w_rank; ++i) {
    TORCH_CHECK(weight.size(i) == bias.size(i), "weight and bias shapes must match");
    TORCH_CHECK(x.size(x_rank - w_rank + i) == weight.size(i),
                "x trailing dimensions must match normalized_shape");
  }

  const int64_t normalized_numel = weight.numel();
  TORCH_CHECK(normalized_numel > 0, "normalized_shape must be non-empty");
  TORCH_CHECK(normalized_numel % 4 == 0,
              "This vectorized kernel requires normalized numel to be divisible by 4");
  TORCH_CHECK(x.numel() % normalized_numel == 0,
              "x numel must be divisible by normalized numel");

  const int64_t rows64 = x.numel() / normalized_numel;
  TORCH_CHECK(rows64 <= INT_MAX && normalized_numel <= INT_MAX,
              "Tensor is too large for this kernel");

  auto y = torch::empty_like(x);
  if (rows64 == 0) {
    return y;
  }

  auto aligned16 = [](const void* p) {
    return (reinterpret_cast<std::uintptr_t>(p) & 0xf) == 0;
  };

  const float* x_ptr = x.data_ptr<float>();
  const float* w_ptr = weight.data_ptr<float>();
  const float* b_ptr = bias.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  TORCH_CHECK(aligned16(x_ptr) && aligned16(w_ptr) &&
              aligned16(b_ptr) && aligned16(y_ptr),
              "All tensors must be 16-byte aligned for float4 access");

  int rows = static_cast<int>(rows64);
  int n4 = static_cast<int>(normalized_numel / 4);
  float inv_n = 1.0f / static_cast<float>(normalized_numel);
  float eps_f = static_cast<float>(eps);

  auto stats = torch::zeros({rows, 2}, x.options());
  c10::cuda::CUDAGuard device_guard(x.device());
  const int num_tiles = (n4 + kThreads - 1) / kThreads;
  int blocks_per_row = std::max(1, std::min(64, num_tiles));
  const int64_t total_units64 =
      static_cast<int64_t>(rows) * static_cast<int64_t>(blocks_per_row);
  TORCH_CHECK(total_units64 <= INT_MAX, "Too many work units");
  const int total_units = static_cast<int>(total_units64);
  const int grid_blocks = total_units;
  TORCH_CHECK(grid_blocks > 0, "Invalid grid size");
  const float4* x4 = reinterpret_cast<const float4*>(x_ptr);
  const float4* w4 = reinterpret_cast<const float4*>(w_ptr);
  const float4* b4 = reinterpret_cast<const float4*>(b_ptr);
  float4* y4 = reinterpret_cast<float4*>(y_ptr);
  float* stats_ptr = stats.data_ptr<float>();
  dim3 block(kThreads);
  dim3 grid(grid_blocks);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  cute_layernorm_reduce_kernel<<<grid, block, 0, stream>>>(
      x4, stats_ptr, rows, n4, blocks_per_row, total_units);
  cute_layernorm_normalize_kernel<<<grid, block, 0, stream>>>(
      x4, w4, b4, y4, stats_ptr, rows, n4, inv_n, eps_f,
      blocks_per_row, total_units);
  cudaError_t launch_err = cudaGetLastError();
  TORCH_CHECK(launch_err == cudaSuccess,
              "CUTE LayerNorm kernel launch failed: ",
              cudaGetErrorString(launch_err));

  return y;
}
"""

cute_layernorm_ext = load_inline(
    name="cute_cooperative_layernorm_ext",
    cpp_sources=ln_cpp_decl,
    cuda_sources=ln_cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Layer Normalization implemented with a single cooperative CuTe/CUDA kernel.
    The nn.LayerNorm member is retained for parameter compatibility, while all
    forward computation is performed by the custom kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.ln = nn.LayerNorm(normalized_shape=normalized_shape)
        self._ext = cute_layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.ln.weight.contiguous(),
            self.ln.bias.contiguous(),
            float(self.ln.eps),
        )

